mapper.select:
select id, task_id, interface_id, statistics_time, collection_count, interface_rate from collect_interface_statistics where statistics_time >= #{startTime} and is_deleted = 0
and task_id = #{taskId}
order by interface_id, statistics_time, id

select id, task_id, interface_id, statistics_time, processing_count, duplicate_count, wild_value_count from data_processing_statistics where statistics_time >= #{startTime} and is_deleted = 0
and task_id = #{taskId}
order by interface_id, statistics_time, id

select id, task_id, interface_name, send_from, transfer_type, transfer_protocol, enabled from collect_interface_config where is_deleted = 0
and task_id = #{taskId}
order by id
